def is_prime(n: int) -> bool:
    """Return whether a positive integer n is prime."""
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True
```

Handles the only two even primes (2 and 3) up front, then tests odd divisors up to `√n`. Returns `False` for `n < 2` since 1 is not prime.

